
document.addEventListener('DOMContentLoaded', () => {
    const links = document.querySelectorAll<HTMLAnchorElement>('a[data-back-to]');

    links.forEach((link) => {
        link.addEventListener('click', (event: MouseEvent) => {
            const target = link.dataset.backTo;
            if (!target) return;

            if (document.referrer.includes(target)) {
                event.preventDefault();
                history.back();
            }
        });
    });
});